mapper.select:
SELECT IFNULL(c.app_name,p.app_type) appName,p.app_type appType,p.link_num linkNum, p.packets packets, p.GByte GByte FROM ( SELECT app_type,SUM(link_num) AS link_num,SUM(c2s_pkt_num+s2c_pkt_num) AS packets, ((SUM(c2s_byte_len+s2c_byte_len)*8)/300/1024/1024/1024) AS GByte FROM traffic_app_statistic WHERE stat_time>= #{beginTime} and stat_time<= #{endTime}
and app_type in
#{item}
GROUP BY app_type ) p LEFT JOIN ui_code_app_dic c ON p.app_type=c.view_code ORDER BY p.GByte DESC
